# The Bench: Supreme Court justices and landmark rulings.
#
# Justices: names, service dates, appointing president and confirmation votes come from the JUDGMENT
# project's restructuring of the Supreme Court Database and Federal Judicial Center records
# (github.com/KaraZajac/JUDGMENT, CC BY-NC 4.0; SCDB: Spaeth, Epstein, Martin, Segal, Ruger & Benesh).
# Lean:
#   * 1937 on: Martin-Quinn scores (Martin & Quinn, mqscores.wustl.edu), the career average of each
#     justice's yearly score. 2020 release through the 2019 term; 2024 release for 2020-2024.
#     Negative = liberal, positive = conservative.
#   * Before 1937: a labeled historians' assessment, 1865 on. Before 1865 justices are "not rated"
#     because today's left/right labels don't fit that Court's main questions (federal vs state power,
#     slavery); a note says what each is known for instead.

# Lean labels from Martin-Quinn career averages
def mq_label(v):
    if v <= -1.0: return "lib"
    if v <= -0.5: return "llib"
    if v < 0.5: return "mod"
    if v < 1.0: return "lcon"
    return "con"

LEAN_NAMES = {"lib": "Liberal", "llib": "Leans liberal", "mod": "Moderate", "lcon": "Leans conservative", "con": "Conservative", "nr": "Not rated"}

